-- One self-contained record following DocumentIngestSchema.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES ($CODEx2aa68a3f0ff2$doc_the_industrial_enterprises_act_2076_2020__2076_industrial-enterprises-act-2020_pdf$CODEx2aa68a3f0ff2$,$CODEx5619d561b9ec$The Industrial Enterprises Act, 2076 (2020)$CODEx5619d561b9ec$,NULL,$CODEx76f3b5a7170a$act$CODEx76f3b5a7170a$,2076,2020,82,$CODEx6f234f056958$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "1 \n \nThe Industrial Enterprises Act, 2076 (2020) \nDate of Authentication \n2076.10.28 (11 Feb. 2020 A.D.) \nAct No. 19 of the year 2076 \nAn Act Made to Amend and Consolidate Prevailing Laws Relating to \nIndustrial Enterprises \nPreamble: Whereas, it is expedient to amend and consolidate the prevailing \nlaws relating to industrial enterprises in order to build a dynamic and robust \neconomy by making a n easy, predictable and effective management of the \nindustrial sector while focusing, respectively, on import substitutions a nd \nexport promotions, through mobilization of the resources available in the \ncountry, to the maximum extent,  to enhance the production of industrial \ngoods or services and employment opportunities by  making the industrial \nenvironment of the country investment friendly and competitive; \nNow, therefore, be it enacted by the Federal Parliament.", "children": []}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-1", "title": "Chapter-1", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short title and commencement : (1) This Act may be cited as the", "content": "“Industrial Enterprises Act, 2076 (2020).” \n  (2) This Act shall come into force immediately..", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definitions: In this Act, unless the subject or the context otherwise", "content": "requires,- \n  (a) “industry” means an industry referred to in section 17; \n \n2 \n \n(b) “industry registration body” means the Department, and this \nterm includes the department or of fice of a Provincial \nGovernment responsible for the administration of industries; \n(c) “one stop service cent re” means the one stop service cent re \nreferred to in section 37; \n(d) “transaction” means the production and distribution by an \nindustry of goods or services as per its objectives  and this \nterm also includes other transaction relating to such \nproduction and distribution; \n(e) “fund” means the fund referred to in section 51; \n(f) “cottage industry” means an industry under clause (b) of \nsub-section (1) of section 17; \n(g) “large industry” means an industry under clause ( e) of sub -\nsection (1) of section 17; \n(h) “prescribed” or “as prescribed” means prescribed or as \nprescribed by the rules framed under this Act; \n(i) “export industry” means an industry, other t han an energy \nindustry, which exports more than at least forty percent of \nits production; \n(j) “Board” means the industrial and investment promotion \nboard formed pursuant to section 20; \n(k) “intellectual property” means  intellectual properties \nincluding pat ents, designs, trademarks, service marks, \ngeographical indications and trade secrets, and this term \n \n3 \n \nincludes matters defined as copyrights by the prevailing \nlaw; \n(l) “medium industry” means an industry under clause (d) of \nsubsection (1) of section 17; \n(m) “Ministry” means the Ministry of the Government of Nepal \nresponsible for matters relating to industry; \n(n) “ national priority  industry” means an industry under \nsection 19; \n(o) “micro-industry” means an industry under clause (a) of \nsubsection (1) of Section 17; \n(p) “Department” means the Department of Industries; \n(q) “small industry” means an industry under clause (c) of \nsubsection (1) of section 17; \n(r) “fixed capital” means the property under section 18.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-2", "title": "Chapter-2", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "3", "title": "Industry to be registered: (1) No person shall establish or operate, or", "content": "cause to be established or operated, an industry without registering it \npursuant to this Act. \n  (2) Notwithstanding anything contained in sub -section (1), an  \nindustry which is in operation after being registered pursuant to the \nprevailing law on industrial enterprises at the time of commencement \nof this Act need not get it re-registered pursuant to this Act. \n \n4 \n \n  (3) An industry established as a branch industry p rior to the \ncommencement of this Act shall get it registered as a separate industry \nby fulfilling the procedures under this Act not later than one year of \nthe commencement of this Act. \n  (4) If an industry intends to produce its products or any part \nthereof in any place different from its previous place or an industry  \nand does not intend to get registered as a separate industry within the \ntime-limit under subsection (3), it may establish and operate such \nbranch industry as a unit industry. \n  (5) When establishing a unit under subsection (4), the procedures \napplicable for the establishment of a new industry, except for \nregistration, under this Act shall be complied with. \n  (6) The concerned unit shall prepare records of the production \nand transaction made by the unit under subsection (4) and also send \nthe records to the main office of the industry.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Provisions relating to registration of industries : (1) A person, firm or", "content": "company that intends to establish any of the following industries \nunder this Act shall m ake an application to the Department for \nregistration in such a form and accompanied by such documents as \nprescribed: \n(a) an industry mentioned in Schedule -1 that requires \npermission; \n(b) an industry  established with foreign investment; \n(c) an industry re lated to any matter set forth in Schedule -5 \nof the Constitution of Nepal; \n \n5 \n \n(d) an industry that falls under the jurisdiction of two or more \nProvinces; \n(e) an industry related to academic consultancy services on \ndiplomatic affairs. \n   (2) The concerned Provi ncial Government shall carry out \nacts relating to the administration of industries including the \nregistration, renewal and regulation of industries other than the \nindustries under subsection (1). \n  Provided that permission shall be obtained in the case of an \nindustry requiring permission. \n(3) Notwithstanding anything contained in subsection (2), the \nFederation shall carry out acts relating to the administration of \nindustries including the registration, renewal and regulation of the \nindustries subject to reg istration, renewal and regulation  by the \nProvincial Government  until the concerned Provincial Government \nmakes law on such industries.  \n(4) Notwithstanding anything contained in subsections (1) and \n(2), industries generating atomic energy, radio -active mat erials, and \nindustries related to atomic energy and uranium -based energy shall be \nestablished and operated by the Government of Nepal only. \n(5) The details or documents to be attached with an application to \nbe made under subsection (1) may also be submitte d through \nelectronic means (online), and the relevant documents may be \nauthenticated by a digital signature. \n \n6 \n \n(6) If, when examining an application received under subsection \n(1), it appears that any required details and documents are not \nsubmitted, the industry registration body shall immediately inform the \napplicant to submit such details or documents within a maximum \nperiod of ninety days. \n(7) If the applicant fails to submit the details or documents \ndemanded under subsection (6) or it does not appear that  the \nprocedures under this Act or the rules framed under this Act are met, \nthe industry registration body may,  by setting out the reasons, reject \nthe application for industry registration. If decision is made to  reject, \nit shall give written information thereof, setting out the reasons, to the \nconcerned applicant within five days after the decision.  \n(8) A person, firm or company that intends to establish an \nindustry other than an industry mentioned in subsection (1) shall make \nan application to the indust ry registration body of the concerned \nProvince for registration of the industry , accompanied by such details \nand documents as provided in the Provincial law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Industry registration certificate to be given: (1) If, when examining the", "content": "application received under section 4, it appears that necessary details \nor documents are submitted , the industry registration body shall \nregister the industry applied for by the applicant and give the industry \nregistration certificate in the prescribed form within five days of  the \nreceipt of such details or documents. \n \n7 \n \n  (2) When giving the industry registration certificate under \nsubsection (1), the following details, among other things, shall be set \nout in the certificate: \n(a) the date of issue of the certificate; \n(b) the perio d for the commencement of commercial \nproduction or transaction; \n(c) the terms to be complied with by the industry; \n(d) such other terms as specified by the industry registration \nbody by making a decision, according to the nature. \n  (3) Notwithstanding anyt hing contained in subsection (1), \nin the case of a micro -industry, application may be made to the \nindustry registration body for the registration of industry within one \nyear after the date of operation of that industry.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Complaint:(1) If the industry reg istration body refuses to register the", "content": "industry, the party who is not satisfied therewith may make a \ncomplaint to the Ministry, for a decision made by the Department, and \nto the Ministry of concerned Province responsible for industries, for a \ndecision made  by the industry registration body of the Province,  \nwithin thirty days. \n  (2) The complaint hearing body shall make required examination \nof a complaint made under subsection (1) and make necessary \ndecision on it within thirty days of the date of the making  of the \ncomplaint.  \n  (3) Other provisions relating to complaints shall be as prescribed. \n \n8", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Adverse effects on environment to be mitigated : (1)  If a n industry", "content": "registered under section 5  is required to carry out environmental \nimpact assessment or initial e nvironmental examination under the \nprevailing law, it shall commence its establishment, operation , \ncommercial production  and transaction only after the approval of a \nreport on such assessment or examination. \n  (2) Notwithstanding anything contained in subs ection (1),  \nenvironmental impact assessment or initial environmental examination \nshall also be carried out if so required under the prevailing law when \nan industry needs to increase its capital  or capacity, add or change its \nobjective, change its location or transfer it to another place. \n  (3) The concerned industry shall be responsible for mitigating \nadverse environmental effects caused or likely to be caused on the \nenvironment in the course of its operation. \n  (4) The industry registration body may, as re quired, monitor \nwhether environmental effects are mitigated under this section  and \ngive a direction, take action or recommend the concerned body for \naction. \n  (5) An industry which is not required to carry out environmental \nimpact assessment or initial env ironmental examination when making \napplication for its registration, shall make a self -declaration, \naccompanied by the reasons and grounds for not requiring to carry out \nsuch assessment or examination, that it will take necessary measures \nto mitigate possi ble adverse effects on the environment from the \nestablishment and operation of the industry. \n \n9", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Permission to be obtained : (1)Notwithstanding anything contained", "content": "elsewhere in this Chapter, permission shall be obtained from the \nBoard prior to registering any industry mentioned in Schedule-1. \n  Provided that permission shall be obtained from the Government \nof Nepal, Council of Ministers, prior to registering any industry \nmentioned in serial number 1 of that Schedule. \n  (2) A person who intends to register an i ndustry requiring \npermission under subsection (1)shall make an application to the Board \nthrough the industry registration body in such a form and \naccompanied by such details as prescribed. \n  (3) If, when examining the application and relevant documents \nunder subsection (2), it appears that the required details or documents \nare attached, the industry registration body shall submit the matter, \nalong with its opinion, to the Board for decision within seven days. \n  (4) The Board shall decide to or not to give p ermission for the \nregistration of industry with respect to the application received under \nsubsection (2) within thirty days. \n  (5) When deciding to give permission under subsection (4), the \nBoard may also specify necessary additional terms and criteria. \n  (6) If the Board decides to give permission under subsection (4) , \nthe Department shall provide a  permit in the prescribed form, along \nwith notice of the decision, to the concerned applicant within five days \nafter the making of the decision. \n  (7) A person who obtains permit under subsection (6) shall apply \nto the industry registration body  for the registration of industry within \n \n10 \n \nthe period mentioned in the  permit. If no application is made within \nsuch specified period, such permit shall ipso facto  become \ninoperative.  \n  (8) If the Board decide s not to give permission for the \nregistration of industry under subsection (4), the industry registration \nbody shall give notice thereof to the applicant within five days after \nthe making of the decision. \n  (9) An appli cant who obtains  permit under subsection (6) shall \nnot sell or dispose  of the permit, transfer the right or change the \nownership in it in any manner , prior to the commencement of \noperation, commercial production or transaction of the industry.  \n  Provided that if any applicant dies prior to the commencement of \noperation, commercial production or transaction of the industry, \nnothing shall prevent his or her heir under the prevailing law from \nperforming the remaining acts in the capacity of applicant.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Information of commencement of operation, commercial production", "content": "or transaction of industry to be given: (1) An industry registered under \nthis Act shall commence its operation, commercial production or \ntransaction within the period mentioned in the industry reg istration \ncertificate and  shall give its information to the industry registration \nbody within thirty days. \n  (2) If any industry fails to commence its operation or commercial \nproduction or transaction under subsection (1), the industry may make \nan applicat ion as prescribed, setting out the reasons, to the industry \nregistration body for the extension of the period in advance of at least \n \n11 \n \nthirty days of the expiration of the period mentioned in the industry \nregistration certificate.  \n  (3) If any industry fail s to apply within the period under \nsubsection (2), the industry may make an application, setting out the \nreasons and grounds, to the industry registration body for the \nextension of the period, within the period mentioned in the industry \nregistration certificate or within six months after the date of expiration \nof that period, upon making payment of the delay fee as prescribed. \n  (4) Upon examination of the application received under \nsubsection (2) or (3), the content appears reasonable, the industry \nregistration body may extend , as prescribed, the period for the \ncommencement of operation or commercial production or transaction \nof such industry , having regard to the progress of works including \nconstruction works to be done for the establishment, and the nature, of \nthe industry. \n  Provided that if the period for the commencement of operation, \ncommercial production or transaction of any industry needs to be \nextended for more than three times, the Board shall submit the matter, \nalong with its opinion, to the Board for approval. \n  (5) If the period is extended under subsection (4), the concerned \nindustry shall commence its operation, commercial production or \ntransaction within that period. \n  (6) If the period for the commencement of operation, commercial \nproduction or transaction of any industry is not extended under \nsubsection (4), written information thereof shall be given to the \n \n12 \n \nconcerned applicant within seven working days after the making of \nsuch decision. \n  (7) If the period for the commencement of operation, commercial \nproduction or transaction of any industry is not extended under \nsubsection (4), the registration permit given to that industry is \nconsidered to be ipso facto inoperative.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "Monitoring and inspection to be made : (1) The Ministry or industry", "content": "registration body may, from time to time, monitor and inspect any \nindustry whether it complies with this Act and the rules framed \nhereunder and the terms mentioned in the industry registration \ncertificate. \n  (2) The employee or official deputed to monitor and  inspect an \nindustry under subsection (1) may, in the course of monitoring and \ninspection, enter the premises of the industry, collect audio -visual and \nother information and data as required, examine necessary documents \nand demand any other information or details. \n  Provided that where a matter of protection of an intellectual \nproperty right under the prevailing law is involved , requiring secrecy \nto be maintained, the prevailing law on intellectual property rights \ngoverns the matter. \n  (3) It shall be the duty of the concerned industry to provide such \ninformation or details demanded under subsection (2). \n  (4) If the information or details received under subsection (3) \nreveals any kind of problem with the operation of such an industry, \n \n13 \n \nthe industry registration body may consult and facilitate the concerned \nindustry as required.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "11", "title": "Approval to be obtained for change of location of industry : (1) If an", "content": "industry registered for operation in a place needs to be shifted to \nanother place for any reason, the industry  shall make an application, \nsetting out the reasons, to the industry registration body in such a form \nas prescribed. \n  Provided that approval of the Department is required to shift it \nfrom one Province to another. \n  (2) If an application is received under subsection (1), the industry \nregistration body may give approval for the shifting of the industry on \nrecommendation of the concerned Local Level where it is to be \nshifted. Information of such approval for the shifting of the industry \nshall also be given to  the Ministry of the concerned Province \nresponsible for industries and the Local Level. \n  (3) Other provisions relating to the  shifting of location of \nindustries shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "Approval required  to increase  capital, capacity and add or change", "content": "objectives of industry : (1) If any industry intends to increase its \nexisting capital or capacity or add, change or alter its objectives , it \nshall make an application in such form as prescribed to the industry \nregistration body for approval thereof. \n  (2) If the contents appear to be reasonable upon examining an \napplication received under subsection (1), the industry registration \nbody shall fulfil the procedures as prescribed and give approval to \n \n14 \n \nincrease the capital, capacity of, add, change or alter the ob jectives of \nsuch industry within ninety days. If the classification of the industry \nchanges by the reason of such increase in capital or capacity or \naddition, change or alteration of objectives, the concerned industry  \nshall update records thereof and have its entry made  in the industry \nregistration certificate. \n  (3) Notwithstanding anything contained in subsections (1) and \n(2), approval of the industry registration body is not required for a \nmicro-enterprise or a cottage and small industry with a fixed cap ital \nnot exceeding ten million rupees which does not require permission, \nto increase its capital or capacity. \n  Provided that if such increase in capital or capacity or addition or \nchange or alteration of objectives requires environmental impact \nassessment or initial environmental examination, a report thereof shall \nbe approved under the prevailing law. \n  (4) If an industry enhances managerial capacity and makes \nproduction exceeding the projection without altering the previously \ninstalled machinery and equi pment, it is not considered to be an \nincrease in capacity.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "Details to be submitted : (1) Every industry shall, after the", "content": "commencement of its commercial production or transaction, submit \nsuch details as prescribed to the industry registration body within  six \nmonths after the end of each fiscal year. \n  (2) The details to be submitted under subsection (1) may also be \nsubmitted through electronic means as prescribed. \n \n15 \n \n  (3) Notwithstanding anything contained in subsection (1), \nan industry shall provide null details for the period even if it remains \nclosed for more than one fiscal year or does not make production or \ntransaction for any reason.  \n  Provided that after such industry gives information of its closure \nto the industry registration body and it is recor ded, it need not provide \nl details for the period of closure.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "Information of closure of industry to be given : If the concerned", "content": "entrepreneur closes an industry registered under this Act for any \nreason or suspends commercial production or transaction of the \nindustry, such entrepreneur shall give information thereof, as \nprescribed, to the industry registration body , within thirty days after \nthe date of such closure or suspension.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "15", "title": "Application for cancellation of registration of industry : (1) If an", "content": "industry cannot be operated for any reason, an application may be \nmade to the industry registration body  for the cancellation of that \nindustry, in such a form and accompanied by such details or \ndocuments as prescribed. \n  Provided that in the case of being insol vent under the prevailing \nlaw, that law prevails. \n  (2) If an application is received under subsection (1) and it \nappears that the concerned industry has settled governmental liability \nincluding tax and other liability to be paid by it, the industry \nregistration body shall cancel the registration of that industry by \nfulfilling the procedures as prescribed.  The information of such \n \n16 \n \ncancellation of registration shall be provided to the concerned \napplicant and all concerned government organizations. \n  (3) Notwithstanding anything contained in subsection (1) or \n(2), in the case of an industry that has undergone the insolvency \nprocess under the prevailing law, that law prevails, and if the industry \nis so liquidated, the liquidator shall give information thereof to  the \nconcerned industry registration body.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "16", "title": "Records to be managed : (1) The industry registration body is", "content": "responsible for safe maintenance of records related to administration \nof industries including registration, renewal, transmission, change in \nname, s hifting location, increase of capacity, increase of capital, \naddition or change of objectives or cancellation of industries. \n  (2) If an industry or person having ownership in such \nindustry requires any documents or records under subsection (1) \nrelated to it, such industry or person may make an application to the \nindustry registration body in such form as prescribed. \n  (3) If an application under subsection (2) is received, the \nindustry registration body shall certify and provide the documents or \nrecords held in the Department, by collecting the prescribed fees. \n  (4) If any record held in the industry registration body is \ndestroyed or cannot be found for any reason, the industry registration \nbody may establish the record on the basis of the documents or \nrecords held in other concerned government bodies and other \ndocuments submitted by the concerned industry and provide \nduplicates under subsection (3). \n \n17 \n \n  (5) If, subsequent to the issuance of duplicates by the \nindustry registration body under subsection (4), t he details relating to \nrecords of that industry are proved to the contrary, the industry \nregistration body may cancel such duplicates by making decision to \nthat effect. \n  (6) No documents or records related to any industry held in \nthe industry registration  body shall be provided to anyone other than \nthat industry or person having ownership in that industry. \n  Provided that if so demanded by any court, government office or \nbody in the course of investigation or government business, nothing is \ndeemed to bar t he provision of records to such court,  government \noffice or body. \n  (7) The industry registration body  shall safely store, the \nrecords, documents or other details related to industries held in that \nbody also in electronic form, . Such electronic records may  be \nexchanged with other government bodies through electronic means by \nmaking procedures to that end.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-3", "title": "Chapter-3", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "17", "title": "Classification of industries: (1) For the purposes of this Act, industries", "content": "are classified into the following: \n(a) Micro-industry: An industry with the following condition s other than \nan industry requiring permission under section 8 is considered to be a \nmicro-enterprise: \n \n18 \n \n(1) with the fixed capital not exceeding two million rupees, excluding \nhouse and land; \n(2) the entrepreneur himself or herself is involved in the operation and \nmanagement of the industry; \n(3) with a maximum of nine workers including the entrepreneur; \n(4) with annual transaction of less than ten million rupees; \n(5) with the capacity  of electric energy, fuel or other oil engine to be \nconsumed by the engine, equipment or machine, if any, used being \ntwenty KW or less. \n(b) Cottage industry: An industry in the following condition is considered \nto be a cottage industry: \n   (1) based on traditional skills and technology; \n(2) labour-oriented and based on specific skills or local raw materials and \nlocal technology, arts and culture; \n(3) with the capacity of electric energy to be consumed by the engine, \nequipment or machine, if any, used being up to fifty KW; \n(4) any industry mentioned in Schedule-2. \n(c) Small industry: An industry with the fixed capital not exceeding one \nhundred fifty million rupees, other than a micro enterprise and cottage \nindustry; \n(d) Medium industry : An industry with the f ixed capital exceeding one \nhundred fifty million rupees but not exceeding five hundred million \nrupees;  \n \n19 \n \n(e) Large industry : An industry with the fixed capital exceeding five \nhundred million rupees. \n(2) The industries mentioned in subsection (1) are classif ied into the \nfollowing on the basis of the nature of goods or services to be \nproduced from such industries: \n(a) Energy-based industry: Industries mentioned in Schedule -3 engaged \nin the business of energy generation; \n(b) Manufacturing industry: Industries m anufacturing goods by using or \nprocessing raw materials, subsidiary raw materials or semi -processed \nraw materials; \n(c) Agriculture and forest product-based industry: Industries mentioned in \nSchedule-4 manufacturing any goods from agriculture or forest \nproduct based raw materials or related to agriculture or forest \nproducts; \n(d) Mining industry: Industries producing any metal or mineral substance \nother than metal by excavating or processing minerals; \n(e) Infrastructure industry : Industries mentioned in Sched ule-5 building \nand operating physical infrastructures; \n(f) Tourism industry : Industries mentioned in Schedule -6 related to \ntourism services; \n(g) Information technology, communication technology and information \ndissemination technology -based industry : Indus tries mentioned in \nSchedule-7 providing services of information, communication or \n \n20 \n \ninformation dissemination technology by using technology for the \ncollection, processing and dissemination of information; \n(h) Service industry: Industries mentioned in Schedu le-8 producing or \nproviding services. \n(3) In the case of an increase in the capital, capacity of, addition, change \nor alteration of the objective of, any industry under section 12, the \nindustry is considered to be ipso facto  classified into the \ncorresponding class under subsection (1). \n(4) Notwithstanding anything contained elsewhere in this section, the \nGovernment of Nepal may , on recommendation of the Board, make \nprovisions to include any industry in the classification of industries or \nplace any industry included in any one class under another appropriate \nclass, by publishing a notice in the Nepal Gazette. \n(5) If any of such cooperatives as prescribed registered under the \nprevailing law intends to register an industry retaining the ownership \nof that cooperative, it may register the industry under this Act. \n(6) If the industries registered prior to the commencement of this Act \nintend to be classified under this Act, the industry registration body  \nmay update the classification by fulfilling the procedures as \nprescribed. \n(7) The Government of Nepal  may make necessary alteration in the \nclassification under subsection (1) or (2) by publishing a notice in the \nNepal Gazette. \n \n21", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "18", "title": "Fixed capital of industry : (1) While  valuating the fixed capital of an", "content": "industry for th e purposes of this Act, valuation is made taking into \naccount the following assets: \n(a) physical structure constructed or reformed on land, underground, \nspace, water or below water; \n(b) physical structure constructed above land (e.g. sewage, internal road,  \ndrinking water related infrastructure, water supply system); \n(c) office, factory, building or ware house of the industry; \n(d) residence building constructed for employees or workers; \n(e) electric supply and related equipment and system; \n(f) machinery, equipment, tools and reserve spare parts thereof; \n(g) means of transportation; \n(h) office goods and equipment of capital nature; \n(i) fixture and furniture; \n(j) communication materials and related equipment and system. \n(2) In addition to the assets set forth i n subsection (1), the following \nexpenses incurred prior to the establishment of an industry  or at \nvarious stages of construction are also valuated as the fixed capital of \nthe industry: \n(a)  technical and inspection expenses to be capitalized; \n(b) pre-investment and preoperational expenses; \n(c) interest expenses to be capitalized; \n \n22 \n \n(d) environmental study and research expenses prior to the operation of \nthe industry.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "19", "title": "Industry of national  priority: The industries mentioned in Schedule -9", "content": "are considered to be industries of national priority .", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-4", "title": "Chapter-4", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "20", "title": "Constitution of Board : (1) An Industry and Investment Promotion", "content": "Board as follows is hereby constituted: \n(a) Minister or Minister of State for In dustry, \nCommerce and Supplies \n-\nChairperson \n(b) Member, National Planning Commission \n(responsible for the industry sector) \n-Member \n(c) Governor, Nepal Rastra Bank  -Member \n(d) Secretary, Ministry (responsible for \nmatters of industries) \n-Member \n(e) Secretary, Ministry of Finance -Member \n(f) Secretary, Ministry of Labour, \nEmployment and Social Security \n-Member \n(g) Secretary, Ministry of Land Management, \nCooperatives and Poverty Alleviation  \n-Member \n(h) Secretary, Ministry of Forest and \nEnvironment \n-Member \n(i) Chief Executive Officer, Investment Board \nof Nepal \n-Member \n(j) Joint Secretary, Industry and Investment \nPromotion Division, Ministry \n-Member \n \n23 \n \n(k) Chairperson, Federation of Nepal \nChamber of Commerce and Industry \n-Member \n(l) Chairperson, Confederation of Nepalese \nIndustries \n-Member \n(m) Chairperson, Federation of Nepal Cottage \nand Small Industries \n-Member \n(n) Chairperson, Women Entrepreneurs \nFederation \n-Member \n(o) Two persons including at least one woman \nentrepreneur nominated by the Ministry \nfrom experts in the industry sector \n-Member \n(p) Director General, Department of Industry -Member \nsecretary \n  (2) Notwithstanding anything contained in clause (a) of \nsubsection (1), if both Minister and Minister of State for Industry, \nCommerce and Supplies a re appointed, the Minister of State acts as a \nmember of the Board. \n(3) If the Board so thinks necessary, it may invite an expert in the \nconcerned field, any official or officer of the Government of Nepal or \nProvincial Government to attend the meeting of the Board. \n(4) The Board meets at least once in every two months and may meet any \ntime as per necessity. \n(5) The member -secretary of the Board shall , in consultation with the \nchairperson of the Board, set the agenda to be deliberated at a meeting \nof the Board, and give notice thereof to every member in advance of at \nleast twenty-four hours of the time for holding the meeting. \n \n24 \n \n(6) If any member of the Board has personal concern or interest in any \nitem of the agenda to be presented for decision at the meeting of the \nBoard, that member shall not participate in the decision -making \nprocess with respect to that item. \n(7) If it appears that a decision is made contrary to subsection (6), the \ndecision becomes ipso facto void. \n(8) The member -secretary of the Board shall authenticate the decisions \ntaken by the Board. \n(9) The secretariat of the Board is seated in the Department. \n(10) Other procedures relating to the meeting of the Board are  as \ndetermined by the Board itself.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "21", "title": "Functions, duties and powers of the Board :(1)In addition to its", "content": "functions, duties and powers specified elsewhere in this Act, the \nfunctions, duties and powers of the Board are as follows: \n(a) to make recommendations to the Government of Nepal for the \nformulation of policies relating to industrial promotion, protection and \npromotion of investment and industrialization and adoption of relevant \npolicy decisions; \n(b) to regularly appraise the policy, institutional, legal, institutional and \nprocedural framework and modus operandi  relating to the overall \nindustrialization of the country and make recommendations to the \nGovernment for necessary reforms; \n \n25 \n \n(c) to make recommendations to the Government of Nepal for the \nadoption of necessary policy decisions on foreign investment and \ntechnology transfer, subject to the prevailing law; \n(d) to make recommendations to the Government of Nepal for the \nformulation of policies relating to industrial pollution control and \nadoption of relevant policy decisions; \n(e) to make comprehensive evaluation and appraisal of the situ ation of \nindustrial development of the country and make suggestions and \nrecommendations to the Government of Nepal for taking necessary \nsteps; \n(f) to hear grievances of entrepreneurs and resolve, or cause to be \nresolved, the problems and make guidance to t he concerned bodies in \nthis respect; \n(g) to make recommendations to the Government of Nepal if it is required \nto make an alteration or change in the level, classification and nature \nof industries; \n(h) to carry out, or cause to be carried out, studies, rese arch woks and \nsurveys as required in the context of enhancing domestic and foreign \ninvestment in the industrial sector; \n(i) to do, or cause to be done, necessary work for building a competitive \nindustrial environment, in effective coordination and harmonio us \ncollaboration with the public, private and cooperative sectors; \n(j) to give policy guidelines on matters requiring coordination between \nthe Province and Local Levels for the development and expansion of \nindustrial enterprises, and make necessary provision for coordination; \n \n26 \n \n(k) to facilitate the removal of the difficulty or confusion, if any,  arising \nin the implementation of any law relating to industry; \n(l) to coordination or facilitate with respect to the operation of the one \nstop service centre; \n(m) to perform, or cause to be performed, other functions as prescribed. \n(2) The Board may delegate any of its functions, duties and powers to a \nbody or officer of the Government of Nepal. \n(3) The Board shall submit an annual report on the functions performed \nby it to the Ministry within thirty days after the date of the end of a \nfiscal year. The Ministry shall publish such a report on its website.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "22", "title": "Secrecy to be maintained: (1) Providing any information that comes to", "content": "one’s knowledge in the course of functioni ng of the Board  to another \nperson in an unauthorized manner or using it for one’s benefit, interest \nor gain, or causing it to be so provided or used, is prohibited. \n  (2) If the chairperson, member, member -secretary a person \nor employee invited to a meetin g does any act contrary to subsection \n(1), he or she is considered to violate the official conduct; and the \nrecord of such a member breaching secrecy shall be maintained.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "23", "title": "Provisions relating to Provincial industry and investment promotion", "content": "board: (1) A Provincial industry and investment promotion board may \nbe constituted under the provincial law to promote investments in \nindustries registered and operated in the Province. \n \n27 \n \n  (2) The functions, duties and powers of the Provincial \nindustry and investment promotion board constituted under subsection \n(1) shall be as follows: \n(a) to regularly appraise the overall industrial promotion in the Province \nand make recommendations to the Provincial Government for \nnecessary reforms; \n(b) to perform necessary functions t o implement policies on industrial \npollution control; \n(c) to make overall evaluation and appraisal of the state of industrial \ndevelopment in the Province, and make suggestions and \nrecommendations to the Provincial Government to take necessary \nsteps; \n(d) to hear grievances of entrepreneurs of industries registered in the \nProvince and resolve, or cause to be resolved, the problems and make \nguidance to the concerned bodies in this respect; \n(e) to carry out, or cause to be carried out, studies, research woks an d \nsurveys, as required, in the context of enhancing domestic investment \nin the industrial sector; within the Province; \n(f) to do, or cause to be done  any necessary work for building a \ncompetitive industrial environment, in effective coordination and \nharmonious collaboration with the public, private and cooperative \nsectors within the Province; \n(g) to make guidance on matters requiring coordination between the \nProvince and Local Level for the development and expansion of \nindustrial enterprises, and make necessary provision for coordination; \n \n28 \n \n(h) to direct the concerned Provincial Ministry to request the Ministry for \nthe removal of any uncertainty, if any, arising in the implementation \nof any federal law relating to industry; \n(i) to coordinat e with the Board thr ough the Ministry with respect to \nservices, facilities that may be provided by the one stop service centre; \n(j) to perform, or cause to be performed, such other functions as may be \nnecessary with respect to promotion of industries registe red in the \nProvince. \n(3) The Provincial industry and investment promotion board may make \nsuggestions and recommendations to the Ministry through the \nconcerned Provincial Ministry on such matters as it thinks necessary \nfor industrial and investment promotion in the Province.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-5", "title": "Chapter-5", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "24", "title": "Exemptions, facilities or concessions relating to income tax : (1)An", "content": "industry registered under this Act is entitled to the exemptions, \nfacilities or concessions under the prevailing laws. \n  (2) Without prejudice to the generality of subsection (1), \nthe following exemptions, facilities or concessions are provided to the \nindustries: \n(a) a manufacturing industry is entitled to twenty percent exemption on \nthe r ate of tax leviable on t he income earned by it, and to an \n \n29 \n \nexemption from income tax by additional five percent of the rate of \ntax leviable on the income earned by it by exporting its products;  \n(b) an infrastructure industr y, such as road, bridge, tunnel, ropeway, \nrailway, tram, trolley bus,  airport, industrial structure and \ninfrastructure complex, is entitled to forty percent exemption on the \nrate of tax leviable on the income earned from investment, if any, in, \nand operation of, the industry; \n(c) a manufacturing industry, other than an industry producing fruit-based \nbrandy, cider, or wine, established in the least developed, \nunderdeveloped and less developed regions mentioned in Schedule-10 \nis entitled to respectively ninety, eighty and seventy percent \nexemption on the rate of income tax leviable under the prevailing law \nfor up to ten years from the date of commencement of commercial \nproduction or transaction of such industry; \n(d) an industry producing fruit-based brandy, cider, or wine established in \nthe l east developed and underdeveloped regions is entitled to \nrespectively forty and twenty -five percent income tax exemption for \nup to ten years from the date of commencement of its transaction; \n(e) a manufacturing industry producing and processing local tea products, \ndairy industries dealing in milk products and industries manufacturing \ntextiles is entitled to fifty percent exemption on the rate of income tax \nleviable on the income earned by it from the sale of its products; \n(f) twenty-five percent exemption o n the rate of income tax leviable on \nroyalty income earned by any person from exporting an intellectual \nproperty right;  \n \n30 \n \n(g) fifty percent exemption on the rate of income tax leviable on the \nincome ear ned by any person from selling by way of transfer of an  \nintellectual property right; \n(h) a manufacturing industry established with the investment of more than \none billion rupees and providing direct employment to more than five \nhundred individuals throughout the year  is entitled to hundred percent \nincome tax e xemption for first five years from the date of \ncommencement of transaction and fifty percent exemption on the \nincome tax for next three years; \n  Provided that a manufacturing industry currently in operation is \nentitled to hundred percent income tax exempti on on the income \nearned from such capacity enhancement for first five years and fifty \npercent exemption on the income tax for next three years if such \nindustry enhances its installed capacity by at least twenty-five percent, \nincreases investment to  two bil lion rupees and provide s direct \nemployment to more than three hundred individuals throughout the \nyear.   \n(i) a licensee person or bod y commencing the commercial \ngeneration, transmission or distribution of hydropower not later than \nthe month of Chaitra 2080 ( mid-April 2024 ) or project generating \nelectricity from solar, wind and bio substance is entitled to hundred \npercent income tax exemption for first ten years and fifty percent \nincome tax exemption for next five years; \n \n31 \n \nProvided that the provisions in force at the time of granting license apply to \nthe licensee person having commenced its commercial production at \nthe time of commencement of this Act.   \n(j) a person exploring and excavating mines (except limestone), \npetroleum products, natural gas and fuel is entitled to hundred percent \nincome tax exemption for first seven years after the date of \ncommencement of commercial transaction and to fifty percent income \ntax exemption for next three years if the person commences such \ntransaction not later than the month of Chaitra 2080 (mid-April 2024); \n(k) an industry related to tourism established with the investment of more \nthan two billion rupees is entitled to hundred percent income tax \nexemption for first five years after the date of commencement of \ntransaction and to fifty percent income tax exemption for next three \nyears; \n(l) such industry related to the operation of  a zoological, geological, bio-\ntech park, and software development, data processing, cyber -café and \ndigital mapping established inside a technology park and information \ntechnology park  as specified by the Government of Nepal  by \npublishing a notice  in the Nepal Gazette  is entitled to fifty percent \nincome tax exemption; \n(m) the following industries providing employment to the following \nnumber of Nepali citize ns are entitled to the following exemptions, \nfacilities: \n(1) a manufacturing industr y andinformation technology industr y \nproviding direct employment to three hundred or more Nepali citizens \n \n32 \n \nthroughout the year is entitled to fifteen percent of tax leviable  on the \nincome of that year; \n(2) a manufacturing industr y and information technology industr y \nproviding direct employment to one thousand two hundred or more \nNepali citizens throughout the year is entitled to twenty -five percent \nof tax leviable on the income of that year; \n(3) such industry is entitled to additional fifteen percent of tax leviable on \nthe income of that year if at least fifty percent of the Nepali citizens \nemployed under clause (1) or (2) are women, Dalit or persons with \ndisabilities. \n(n) an industry is entitled to deduction, for the purposes of income tax, of \nexpenses made in long -term interest or welfare activities for  its \nlabours and employees, such as life insurance, health facilities, \ncontributory social security, education and training, child care cent re \nand sports and exercise for physical fitness;  \n(o) a manufacturing industry is entitled to deduction, for the purpose of \ncalculating income tax, of maintenance expenses, training expenses \npaid to such trainee workers  if at least ten percent of its total strength \nof human resources are trainee workers, and of expenses incurred in \ndevelopment of production capacity of human resources in the \nindustry; \n(p) an industry is entitled to deduction of expenses for the same year up to \nfifty percent o f the adjusted taxable income of the industry business \nout of the expenses incurred in the systems and equipment preventing \nand controlling pollution or causing minimum effects on the \n \n33 \n \nenvironment by recycling or reusing waste materials, and to making \ndepreciation by capitalizing the expenses exceeding the ceiling of \nadjusted taxable income of such industry business in the beginning of \nthe next income year; \n(q) an industry is entitled to deduction for the purpose of income tax of all \nexpenses invested in machinery or equipment contributing to reducing \nconsumption of energy by enhancing energy efficiency; \n(r) an industry is entitled to deduction of expenses up to fifty percent of \nthe adjusted taxable income of all industry business operated by that \nperson out of the expenses incurred in the enhancement of \nentrepreneurship, research and development and creation of new \ntechnology for enhancing productivity of the industry, and to making \ndepreciation by capitalizing the expenses exceeding the ceiling of \nadjusted taxable income in the beginning of the next income year; \n(s) an industry is entitled to deduction for the purpose of income tax of \nthe expenses not exceeding the prescribed ceiling incurred in market \npromotion, survey and advertisement related to the industry business; \n(t) an industry is entitled to deduction for the purpose of income tax of \nsuch expenses as prescribed incurred for the protection of physical \nproperty of the industry and expenses for net payment of premium for \ninsurance thereof; \n(u) an industry is entitled to deduction for the purpose of income tax of \nthe expenses incurred by it in the protection in Nepal of an industrial \nproperty under an intellectual property right registered in Nepal; \n \n34 \n \n(v) an industry is entitled to deduction for the purpose  of income tax of \nthe fees paid for the registration in a foreign country of an intellectual \nproperty right acquired by it for the protection of such right; \n(w) an industry is entitled to reduction of one hundred thousand rupees or \nfive percent of the adju sted taxable income of th e industry for that \nincome year, whichever is less, out of the amount donated or gifted by \nthe industry to an entity enjoying tax exemption; \n(x) an industry is entitled to deduction in whole or in part, for the purpose \nof assessment of income, of the amount spent or donated by it for any \nsuch act as may be specified by the Government of Nepal in any \nspecific situation, by publishing a notice in the Nepal Gazette. \n(3) Notwithstanding anything contained in subsection (2), a tobacco \nindustry and a liquor industry, other than an industry mentioned in \nclause (d) of that subsection, are not entitled to any of the said \nexemptions and facilities. \nProvided that such industry is entitled to deduction of actual expenses made \nfor business promot ion, including the expenses made in long -term \ninterest or welfare activities of its labours and employees under the \nprevailing law, expenses invested in the systems and equipment \npreventing and controlling pollution, re -processing waste materials \nand causing minimum effects on the environment, expenses invested \nin machinery, equipment contributing to reducing energy consumption \nby enhancing energy efficiency, and expenses incurred in research and \ndevelopment. \n \n35 \n \n(4) An industry which  may enjoy more than one ex emption under this \nSection with respect to the same income  is entitled to only one \nexemption that it chooses. \n(5) An industry, other than a tobacco industry, alcohol industry and \ncasino, is entitled to hundred percent exemption on dividend tax \nleviable on such capitalization against the distribution of dividends if \nthe industry ca pitalizes its accumulated profit in shares for  the \nexpansion of the same industry or another manufacturing , energy-\noriented or agriculture and forest product based industry. \n(6) A cottage industry and small industry which are in operation upon \nregistration at the time of the commencement of this Act and which \ncome in operation upon registration under this Act  with the fixed \ncapital of less than ten million rupees are entitled to fif ty percent  \nexemption on income tax leviable on them.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "25", "title": "Exemptions, facilities or concessions relating to customs duty : An", "content": "industry registered under this Act is entitled to the following customs \nduty exemptions: \n(a) for exports by  those industries  without the facility of  bonded \nWarehouse or passbook , the Ministry of Finance  shall determine the \nrate of duty draw back and publish a notice in the Nepal Gazette. The \nMinistry must refund the amount of duty draw back according to the \nrate so determined, through the One Stop Service Centre; \n(b) if an industry which has not obtained a license of bonded warehouse is \nto export its products through a letter of credit or prevailing banking \nsystem or sells them within Nepal in foreign currency, it may import \n \n36 \n \nsuch r aw materials or subsidiary raw materials and packaging \nmaterials that is not produced in Nepal as required for the production \nof such goods by depositing customs duty leviable on such import, \nsubject to the prescribed terms and procedures; \n(c) notwithstanding anything contained in clause (b), such  industry is \nentitled to the facility under clause (b) if the Department certifies that \nsuch packagingmaterials are not produced in Nepal and recommends \nfor that facility; \n(d) customs duty on  raw materials, subsi diary raw materials, and \npackaging materials as required for production by an industry is \ngenerally less by one level  than customs duty  on imports of finished \ngoods produced from such raw materials; \n(e) minimum customs duty rate shall be applied  on impor t of a \nmachinery, generatoror industrial equipment with the capacity of tenor \nmore Kilowatt imported by an industry for its commercial purpose; \n(f) minimum customs duty  rate shall be applied   for a machinery and \nscientific equipment imported by a laborator y testing quality for the \npurpose of testing quality and a machinery and equipment imported by \nan industry for research and development; \n(g) an industry producing intermediate goods used in industrial goods to \nbe exported is entitled to refund of the custo m duty paid by that \nindustry on the produced goods based on the quantity of export.  \n  Provided that such amount is not refunded if application is not \nmade for such refund within one year after the export.  \n \n37", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "26", "title": "Other facilities and concessions for micro -industries:(1)", "content": "Notwithstanding anything contained in the prevailing law, no fee or \ncharge is levied for the registration of a micro-industry under this Act. \n  (2) A micro-industry which is in operation upon registration \nat the time of commencement of this Ac t and comes into operation \nupon registration under this Act is entitled to  full income tax \nexemption.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "27", "title": "Additional facilities for female entrepreneurs : (1) Notwithstanding", "content": "anything contained in the prevailing law, if an industry or firm is \nregistered with the sole ownership of a female entrepreneur, it is \nentitled to thirty -five percent exemption on the fee or charge leviable \non the registration of that industry or firm under the prevailing law. \n  (2) Notwithstanding anything contained in the prevailing \nlaw, an industry registered with the sole ownership of a female \nentrepreneur is entitled to twenty percent exemption on the fee or \ncharge leviable under the prevailing law on the registration of an \nindustrial property to be used in that industry. \n  (3) If a female entrepreneur intends to establish a new \nindustry within an industrial zone or industrial village, the body \noperating such area shall be given priority to providing a space. \n  (4) If an industry with the sole ownership of a female \nentrepreneur requ ests for a loan for the purpose of exporting its \nindustrial products, an export loan may be provided as prescribed \nthrough the banking system from a fund disbursing loans for female \n \n38 \n \nentrepreneurs on the basis of financial situation of the female \nentrepreneur.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "28", "title": "Special provisions relating to industries operated in industrial region :", "content": "The Government of Nepal may make special provisions on incentives, \nfacilities and concessions for industries operated in an industrial zone, \nindustrial cluster, industrial corridor and industrial village.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "29", "title": "Additional facilities and concessions : In addition to the exemptions,", "content": "facilities and concessions mentioned in sections 24, 25, 26, 27 and 28, \nthe following additional facilities and concessions may be provided to \nthe following industries: \n(a) possessory right of a forest within any specific area may be provided \non bond or lease under the prevailing law to a forest product -based \nindustry by specifying necessary terms; \n(b) electricity generated by an industry for its own pur pose is exempted \nfrom any fee or royalty payable on it under the prevailing law; \n(c)  if an industry intends to sell excess of electricity generated by it for \nits own purpose, it may be sold at the rate set by mutual consent under \nthe prevailing law; \n(d) the Government of Nepal may,  provide additional facilities and \nconcessions  by publishing a notice in the Nepal Gazette, s to export-\noriented industries and such industries as prescribed established in a \nspecial economic zone or governmental or private industrial zone; \n(e) the Government of Nepal may, on recommendation of the Board and \nby a notification in the Nepal Gazette, provide additional facilities and \nconcessions to those industries of national priority or  uses maximum  \n \n39 \n \namount of domestic raw materi als, labour and skills or inventing \ntechnology or goods within Nepal; \n(f)  the Government of Nepal may grant exemption on demand charge \nbeing levied on electricity tariff payable  by industry in proportion to \nthe time of non-supply of electricity, in such grounds and by following \nsuch procedures as prescribed; \n(g) the Government of Nepal may provide such grant and prescribed by a \nnotification in the Nepal Gazette as seed money to a cooperative, \nmicro-enterprise, cottage and small industry in the least devel oped \narea;  \n(h) permission may be granted to an industry in operation with foreign \ninvestment to import goods produced by its principal company abroad \nfor a certain period on such terms and within such ceiling as \nprescribed, for development and promotion of  market for new goods; \n(i) the Government of Nepal may provide such incentives, exemptions, \nfacilities or concessions , as  prescribed, to the manufacturing \nindustries, agriculture and forest product -based industries  and \nminerals industr ies under  subsection (2) of section 17, other than \ntobacco and liquor industries; \n(j) exemption may be granted on customs duty  for the imports by micro, \ncottage and small industries of novel technology such as machinery \nand equipment; \n(k) the Government of Nepal may make spe cial provisions in relation to \nincentives, exemptions, facilities or concessions for industries \n \n40 \n \nestablished in an industrial zone, product specific zone and industrial \nvillage; \n(l) the Government of Nepal may provide additional incentives, \nexemptions, faci lities or concessions to industries established in the \nleast developed, undeveloped and under developed regions.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "30", "title": "Provisions relating to land : (1) The concerned entrepreneur shall", "content": "purchase such land under the prevailing law on his or her own as is \nnecessary for an industry registered under this Act or the prevailing \nlaw.   \n  Provided that if an entrepreneur operating any of the industries as \nprescribed fails to purchase such land as is necessary for the industry \nand makes a request setting out the matter that the land be purchased \nor provided, the industry registration body shall make necessary \ncoordination and facilitation on the purchase or provision of land. \n  (2) The procedures on coordination and facilitation and \nother provisions relating to provision of land are as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "31", "title": "Provision of land on lease: (1) If an industry of national priority needs", "content": "a land under ownership of the Government for its operation, the \nindustry may make an application, as prescribed, setting out the area \nof the land requ ired for it, to the industry registration body for the \nprovision of the land. \n  (2) If an application is received under subsection (1), the \nindustry registration body shall submit the matter to the Ministry to \nfurther necessary action on the provision of l and required for the \nindustry. \n \n41 \n \n  (3) If an application is received under subsection (2), the \nGovernment of Nepal may, under the prevailing law, provide such \nland on lease to the concerned industry for the purpose of operation of \nthe industry. \n  (4) The amount to be paid by the industry in consideration \nfor the lease of land under ownership of the Government of Nepal \nunder subsection (3) and other terms on lease are as set out in the \nagreement between the Government of Nepal and the concerned \nindustry. \n  (5) If an industry in operation upon obtaining any land on \nlease under this Section fails to operate for any reason, the lease \nagreement of the land provided by the Government of Nepal under \nsubsection (3) becomes ipso facto void, and such land is considered to \nbe ipso facto returned without any terms to the Government of Nepal. \n  (6) Other provisions on the provision of land on lease to \nindustries shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "32", "title": "Exemption on land ceiling : (1) If any industry requires such land that", "content": "exceeds the ce iling of land allowed under the prevailing law,  the \nindustry may make an application to the industry registration body to \nhave exemption from the ceiling with respect to the land exceeding \nthe ceiling. \n  (2) The industry registration body shall examine, as  \nrequired, the application received under subsection (1) and submit a \nreport along with its opinion to the Ministry. \n \n42 \n \n  (3) On the application received under subsection (1), the \nGovernment of Nepal may, subject to the prescribed criteria, grant \nexemption so  that the industry can hold land exceeding the ceiling, \naccording to the need of, and as mentioned in the approved scheme or \nproject proposal of, the industry. The land so exempted from the \nprovision of  ceiling may not  be used for other purpose than the \npurpose for which it has been exempted. \n  (4) The industry registration body may monitor , or cause to \nbe monitored,  as prescribed , whether the industry has used the land \nexempted from the ceiling under the prevailing law as per the \napproved objective and give necessary direction. \n  (5) If the industry is found not to comply with the direction \ngiven by the  industry registration body under sub -section (4), the \nGovernment of Nepal may withdraw, , the land exceeding the ceiling \nwhich such industry is allowed to h old, in accordance with the \nprevailing law, without any condition. \n  (6) An industry permitted to hold land exceeding the ceiling \nunder the prevailing law may not sell, distribut e, or otherwise transfer \nright in, or borrow a loan from a bank and financial institution against \nthe security of, the land so held exceeding the ceiling. \n  (7) The quantity of maximum land allowed to be held by an \nindustry on the basis of the need, capital and nature of the industry, \nprovisions relating to the provision of land in excess of the ceiling, \ncriteria including conditions to be observed by the industry in that \nrespect shall be as prescribed subject to the prevailing law on land. \n \n43", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "33", "title": "Guarantee of incentives, exemptions, facilities or concessions : (1) No", "content": "provision  shall be made lessening the incentives, exemptions, \nfacilities or concessions provided to an industry under this Act. \n  Provided that no provision of this section bars the provision of \nadditional incentives, exemptions, facilities or concessions. \n  (2) An industry  that is in operation upon permission or \nregistration under the Industrial Enterprises Act, 2073 ( 2016) \nprevailing immediately before the commencement of this Act is \nentitled to the incentives, exemptions, facilities or concessions in \naccordance with that Act for which period is specified under that Act \nand to the incentives, exemptions, facilities or concessions under this \nAct in the case of the incentives, exemptions, facilities or concessions \nfor which period is not specified. \n  (3) An industry which was  registered or has obtained \npermission before the commencement of this Act but commences its \ncommercial production or transaction only after the commencement of \nthis Act shall be entitled to the incentives, exemptions, facilities or \nconcessions under this Act. \n  Provided that if the period of incentives, exemptions, facilities or \nconcessions under the prevailing law on industrial enterprises \nprevailing at the time of registration or permission of such industry \nexceeds the period of incentives, exemptions, f acilities or concessions \nunder this Act or if such incentives, exemptions, facilities or \nconcessions are not available under this Act, the industry shall be \n \n44 \n \nentitled to the incentives, exemptions, facilities or concessions under \nthen prevailing law on industrial enterprises. \n  (4) The procedures relating to incentives, exemptions, \nfacilities or concessions to be provided to industries shall be as \nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "34", "title": "Nationalisation or expropriation not to be made : (1) No industry", "content": "registered under this Act may be nationalised. \n(2) No industry may, except for a public purpose, be expropriated directly \nor indirectly. If it is required to expropriate it for the public purpose, \ndue process under the prevailing law shall be fulfilled.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "35", "title": "Provision relating to industr ial security : The Government of Nepal", "content": "shall, as required,  provide industrial security , as prescribed,  to any \nindustry established under the prevailing law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "36", "title": "Prohibition on misusing incentives, exemptions, facilities or", "content": "concessions: (1) Any incentives, e xemptions, facilities or concessions \nwhich an industry obtains under this Act shall be used only for the \nsame purpose for which they are provided. \n  (2) If any industry does any act contrary to this Act or the \nrules framed hereunder, no incentive, exemptio n, facility or \nconcession under this Chapter may be provided to that industry.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-6", "title": "Chapter-6", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "37", "title": "Establishment of One stop  Service Cent re: (1) For the purpose of", "content": "providing  the incentives, exemptions, facilities o r concessions easily \n \n45 \n \nto those industries or investors  entitled under this Act and other \nprevailing laws and performing the functions to be discharged by \nvarious bodies of the Government of Nepal through one place in a \ntimely manner and delivering industry  administration related services \nfrom the permission to establish, registration, expansion and \nliquidation of, industries, the Government of Nepal may establish and \nbring into operation a One stop Service Centre, as prescribed. \n  (2) The place where the One stop  Service Cent re under \nsubsection (1), services to be rendered to industries through the Centre \nand institutional representation in the Centre  shall be as prescribed. \n  (3) The concerned body shall designate a required number \nof employees for institu tional representation in the One stop Service \nCentre. When so designating, the competent authority shall also \ndelegate necessary powers to such employees, subject to the \nprevailing law. \n  (4) Other provisions relating to the One stop Service Centre \nshall be as prescribed. \n  (5) The Government of Nepal shall, by publishing a notice  \nin the Nepal Gazette, form a One stop  service operation committee \nuntil the establishment of the One stop  Service Cent re under \nsubsection (1).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "38", "title": "Functions, duties and powers of the One stop Service Centre: (1) The", "content": "functions, duties and powers of the One stop  Service Cent re are as \nfollows: \n \n46 \n \n(a) to perform functions related to industry and business  administration, \nincluding registration, permission or licensing, r enewal, approval for \ntransaction, enhancement of capacity of , and dissolution(except \ninsolvency) of, any company, firm or industry  under the prevailing \nlaw, \n(b) to perform functions related to approval of foreign investment  under \nthe prevailing law, \n(c) to p erform functions related to labo ur permit and consent for work  \napproval under the prevailing law, \n(d) to perform functions related to visa facility under the prevailing law; \n(e) to perform functions related to initial environmental examination and \nenvironmental impact assessment under the prevailing law; \n(f) to coordinate with concerned bodies with respect to provision of \ninfrastructure services such as electricity, water, means of \ncommunication, land ,  roads required for industries and perform \nfunction related to focal point between other bodies; \n(g)  to implement, or cause to be implemented, decisions made by the \nGovernment of Nepal on the provision of the incentives, exemptions, \nfacilities or concessions to which industries and investors are entitled \nunder the prevailing laws; \n(h) to perform functions related to approval of foreign currency exchange \nunder the prevailing law; \n(i) to provide Permanent Accounts Number under the prevailing law; \n \n47 \n \n(j) to perform function on facilitating the obtaining of the export -import \ncode an d bonded warehouse to be provided by the Department of \nCustoms and the Department of Commerce, Supplies and Consumer \nInterest Protection; \nk) to perform such functions as delegated by the Board out of the \nfunctions, duties and powers conferred on it; \n(l) to receive applications on matters requirin g institutional approval \nincluding on mines required for industries and make institutional \ncoordination for the provision of approval; \nm) to identify and receive all the documents required for the registration \nof industrial enterprises electronically, by developing and enforcing an \nelectronic system that links all bodies within it; \n(n) to make necessary coordination and facilitation in the acquisition of \nlaw required for industries, assistance in the provision of lan d on \nlease, and make necessary coordination on the provision of land \nexceeding the ceiling; \n (o) to provide permission under the prevailing law for the goods requiring \nimport permission or recommend for that purpose; \n(p) to establish and operat e an investment portal and provide investment \nrelated notifications and information; \n(q) to perform functions related to recommendation and facilitation of \nevery kind required for industrial enterprises; \n(r) to implement, or cause to be implemented, decisions or direc tions of \nthe Ministry and Board; \n \n48 \n \n(s) to perform such other functions as may be specified by the \nGovernment of Nepal, by publishing a notice in the Nepal Gazette. \n(2) The concerned body shall implement a decision made by the One stop \nService Centre under this section. \n(3) Provisions relating to the operation, management of the One stop  \nService Cent re and the services, facilities and concessions to be \nprovided by the Centre and procedures shall be as prescribed.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-7", "title": "Chapter-7", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "39", "title": "Identification of sick industries : (1) If an industry which has been in", "content": "operation for a minimum of five   years after the date of \ncommencement of its commercial production or transaction , and in a \ncapacity that is thirty percent or less of its install ed capacity for the \nlast three consecutive years because of a circumstance beyond control \nbut not because of its intentional default or managerial weakness  is \nbeing operated in loss for the three consecutive years, the Government  \nof Nepal may declare such  an industry as a sick industry on the basis \nof such criteria and on the pursuance of such procedures as prescribed. \n  (2)  If it appears from the scheme or project proposal \nsubmitted by an industry in a state of closure upon being sick under \nsubsection (1) and study carried out by the Ministry that the industry \nmay revive its operation if certain exemption, facility or concession is \nprovided to it, the Government of Nepal  may provide such \nexemption, facility or concession as prescribed for a certain period  for \nthe rehabilitation, reconstruction and management of such an industry. \n \n49 \n \n  (3) If a cooperative makes a proposal, with the consent of \nthe investor, for the operation of any industry declared sick by the \nGovernment of Nepal under subsection (1), the indu stry may be \ncaused to be operated through such a cooperative subject to the \nprescribed terms, having regard to, inter alia , the capacity of the \ncooperative, appropriateness and feasibility.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "40", "title": "Classification of sick industries : The industries identified u nder", "content": "section 39 may be classified into fully sick, sick and oriented to be \nsick industries on the basis of such criteria as prescribed, and such \nnecessary provisions as prescribed may be made for the management \nof such industries.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "41", "title": "Facilities, concessio ns and exemptions related to sick industries :", "content": "Notwithstanding anything contained in the prevailing laws, the \nGovernment of Nepal may grant exemption in full or in part on duty, \nfee or tax on any machinery, tools, or equipment to be imported by an \nindustry identified as a sick industry under Section 39 or classified \nunder Section 40 for its expansion, re-structuring or diversification.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "42", "title": "Institutional provision relating to sick industries :(1) The Government", "content": "of Nepal may form a committee including experts i n the concerned \nfield to make suggestions for the identification, classification, \nrehabilitation, restructuring and management of sick industries under \nthis Chapter. \n  (2) The structure, functions, duties and powers of the \ncommittee formed under subsection (1) shall be as prescribed. \n \n50", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-8", "title": "Chapter-8", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "43", "title": "Punishment: (1) If any person operates an industry without", "content": "registration under section 3, the industry registration body may require \nimmediate closure of the industry and impose the following fine: \n  (a) five thousand rupees, if it is a micro-industry; \n  (b) twenty five thousand rupees, if it is a cottage and small \nindustry; \n  (c) fifty thousand rupees, if it is a medium industry; \n  (d) one hundred thousand rupees, if it is a large industry. \n  (2) If an industry acts contrary to its objective, the Ministry \nmay, on the recommendation of the industry registration body, impose \nthe following fine on the industry: \n(a) a fine not exceeding two thousand rupees, if it is a micro-enterprise; \n(b) a fine of fifty thousand rupees, if it is a cottage and small industry; \n(c) a fine not exceeding one hundred thousand rupees, if it is a medium \nindustry; \n(d) a fine not exceeding five hundred thousand rupees, if it is a large \nindustry. \n  (3) If an industry fails to give information on the \ncommencement of its operation or commercial production or \ntransaction within the period specified under section 9, the Ministry \n \n51 \n \nshall, upon the recommendation of the industry registration body, \nimpose the following fine on the industry: \n(a) a fine not exceeding two thousand rupees for every six months, if it is \na micro-industry; \n(b) a fine of ten thousand rupees for every six months, if it is a cottage \nand small industry; \n(c) a fine not exceeding twenty -five thousand rupees for every six \nmonths, if it is a medium or large industry. \n(4) If an industry shifts its location without obtaining approval under \nsection 11 or increases its capital, enhances its capacity or add or \nchanges its objective without obtaining approval under section 12, the \nMinistry may, on the recommendation of the industry registration \nbody, impose the following fine on the industry: \n(a) a fine not exceeding five thousand rupees, if it is a micro-industry; \n(b) a fine of twenty -five thousand t o fifty thousand rupees, if it is a \ncottage and small industry; \n(c) a fine of one hundred thousand to three hundred thousand rupees, if it \nis a medium or large industry; \n(d) hundred percent additional fine in addition to the fine imposable under \nclause (b) or (c) if it is an industry requiring permission under section \n8. \n(5) If an industry fails to provide the prescribed information under section \n13 within the specified period, the industry registration body may \nimpose the following fine on the industry:   \n \n52 \n \n(a) a fine of one thousand rupees, if it is a micro-enterprise; \n(b) a fine of five thousand rupees, if it is a cottage and small industry; \n(c) a fine of ten thousand rupees, if it is a medium industry; \n(d) a fine of twenty-five thousand rupees, if it is a large industry. \n(6) If an industry does an act contrary to section 36, the Ministry may, on \nthe recommendation of the industry registration body,  withhold any \ntime any incentive, exemption, facility or concession  provided to the \nindustry, recover the amoun t equal to such incentive, exemption, \nfacility or concession or impose a fine equal to that amount. \n(7) If an industry does not perform the corporate social responsibility \nunder section 54, the Ministry may, on the recommendation of the \nindustry registration body, impose a fine to be set by one point five \npercent of the yearly net profits of the industry. The Ministry shall \nimpose an additional fine at the rate of zero point five percent of the \nyearly net profits for each year on a n industry which does not perform \nsuch responsibility for a period exceeding one fiscal year. \n(8) If an industry fails to comply with any terms to be complied with \nunder this Act or the rules framed hereunder or any direction given by \nthe Ministry upon recommendation of the industr y registration body, \nfrom time to time, the industry registration body may impose the \nfollowing fine on the industry: \n(a) a fine not exceeding five thousand rupees, if it is a micro-enterprise; \n(b) a fine of fifty thousand to one hundred fifty thousand rup ees, if it is a \ncottage and small industry; \n \n53 \n \n(c) a fine of one hundred fifty thousand to three hundred thousand rupees, \nif it is a medium industry; \n(d) a fine of two hundred fifty thousand to three hundred thousand rupees, \nif it is a large industry. \n(9) The Ministry may, on recommendation of the industry registration \nbody, impose the following fine on an industry which does any act \ncontrary to this Act or the rules framed here  under, other than that set \nforth in this section:  \n(a) a fine not exceeding fifteen thousand rupees, if it is a micro-enterprise; \n(b) a fine of fifteen thousand to thirty thousand rupees, if it is a cottage \nand small industry; \n(c) a fine of thirty thousand to fifty thousand rupees, if it is a medium \nindustry; \n(d) a fine of fifty thousand to one hundred thousand rupees, if it is a large \nindustry. \n(10) When imposing a fine under this section, additional fine of fifty \npercent of the fine imposable under this section shall be imposed on \nan industry requiring permission under section 8. \n(11) Notwithstanding anything contained in this section, provisions on \nimposition of fine on and taking action on any of the industries to be \nregistered and regulated by the Province and Local Level shall be as \ndetermined by the concerned Provincial or Local law. \n \n54", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "44", "title": "To be recovered as government due : The amount of fine imposed", "content": "under this Act shall be recovered as a government due under the \nprevailing law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "45", "title": "Opportunity to be heard : When imposing punishment on an industry", "content": "under this chapter, the industry shall be afforded an opportunity to be \nheard.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "46", "title": "Provisions relating to appeal : (1) If not satisfied with an order of", "content": "punishment made under this Chapter, appeal may be made to the High \nCourt within thirty -five days after the date of notice of the \npunishment. \n  (2) Appeal may be made to the concerned District Court in \nthe case of a decision made by the Local Level industry registration \nbody and to the concerned High Court in the case of punishment \nimposed by the Provincial industry registration body or by the \nDepartment.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-9", "title": "Chapter-9", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "47", "title": "Provisions relating to  Special Economic Zone: Provisions relating to", "content": "an economic zone, inland economic zone, export promotion zone,  \nexport processing zone,  special economic zone, special commercial \nzone, tourism or any  other zone, for the performance of industrial \nactivities extensivelyshall be as provided in the prevailing laws.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "48", "title": "Provisions relating to Nepal business forum : (1) The Government of", "content": "Nepal may form a Nepal business forum including representation of \nthe p rivate sector with the objective of promoting regular dialogues \n \n55 \n \nand collaboration between the public and private sectors on matters of \neffective implementation of policies and laws related to industry \nbusiness, and coordination and facilitation, identifyin g difficulties, \nobstructions and problems that may arise in the operation of industry \nbusiness and promotion of investments and making required \nsuggestions and recommendations to the Government of Nepal, \nassisting the implemen tation and monitoring of such \nrecommendations, and providing an institutional basis for regular, \nresult-oriented and transparent dialogue between the public and \nprivate sectors.  \n  (2) Provisions relating to the formation, structure, \nfunctions, duties and powers of the Nepal business f orum and other \nprovisions shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "49", "title": "Industrial human resource : (1) Human resource required for an", "content": "industry shall be fulfilled from Nepali citizens. \n  (2) Notwithstanding anything contained in subsection (1), if \nsuch human resource with an y specific skill or competency required \nfor an  industry is not available fr om Nepali citizens in spite of the \npublication of an advertisement in a newspaper of national circulation \nor for a senior level management post, the industry may, on the \nrecommendation of the Department under subsection (3), appoint a \nforeign citizen for a maximum of five years by obtaining labour \npermit under the prevailing labour law. \n  (3) When making a recommendation for the purpose of \nsubsection (2), the industry registration b ody shall ascertain that the   \n \n56 \n \nindustry has made an effort to fulfil the human resource with the  \nspecific skill or competency as demanded from Nepali citizens, the \nhuman resource with such skill or competency is required for the \nindustry and such human res ource is not available in Nepal and \nrecommend to the Department of Labour for labour permit. \n  (4) If a foreign citizen appointed under subsection (2) is a \ntechnical person of speci alized  skill and such human resource cannot \nbe available in Nepal, such hu man resource may be re -appointed for \nan additional period not exceeding two years by obtaining permit \nunder subsection (3). \n  (5) If a foreign citizen is appointed to any industry under \nsubsection (2), he or she may repatriate seventy percent of the \nremuneration received by him or her in foreign currency from Nepal. \n  (6) No labour engaged in an industry may carry out any \nkind of activity causing an obstruction or hindrance in the operation or \nproduction of the industry. The labours engaged in the industry shall \nput their demands before the management peacefully in fulfilment of \nthe procedures determined by the prevailing labour law and shall \nresolve through mutual understanding. \n  (7) Individual or collective disputes arising between the \nlabours engaged in an industry and the industry are settled under the \nprevailing labour law. \n  (8) If an industry is closed because of any kind of activities \ncausing obstruction or hindrance in the operation and production of \nthe industry on the part of its labours, the conc erned industry or \n \n57 \n \nenterprise shall not be bound to provide remuneration to the labours \nand employees who so close the industry or do not work, for the \nperiod during which work is not so done.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "50", "title": "Production  through contract: (1) Any industry which is in o peration", "content": "upon registration under the prevailing law may produce any part of its \nproduction or such subsidiary goods or services as required for the \nindustry, except its main production, by making a contract or sub -\ncontract with another industry. \n  (2) If a n industry produces goods or services in a certain \nquantity on the basis of a contract or sub-contract under subsection (1) \nby fulfilling such criteria as prescribed for an export industry, such \nincentives, exemptions, facilities and concessions as prescri bed may \nalso be provided to such an industry. \n  (3) Other provisions relating to production upon a contract \nor sub-contract shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "51", "title": "Industy and investment promotion fund: (1) The Government of Nepal", "content": "establishes a n industryand investment  promotion fund, for the \npromotion and protection of industrial investment in the country. \n(2) The following amounts are credited to the fund under subsection (1):   \n(a) amount received from the Government of Nepal; \n(b) amount received from any native person or organization; \n(c) returns of investments from or amounts in the micro, cottage and \nsmall enterprise development fund, micro, cottage and small industry \nloan disbursement fund, technology development fund, female \n \n58 \n \nentrepreneurship devel opment fund, ven ture capital fund, sick \nindustry rehabilitation, restructuring and management fund and \nindustrial investment protection and promotion fund existing at the \ntime to commencement of this Act; \n(d) amount of bilateral or multilateral grant or assistance received from \nany foreign government, international organization; \nProvided that p rior to obtaining a grant or assistance from a foreign \ncountry, international organization , approval of the Government of \nNepal, Ministry of Finance shall be obtained. \n(3) The amount  of the fund under subsection (1) may be spent in the \nfollowing acts: \n(a) development of micro-industries, cottage and small industries; \n(b) development of technology; \n(c) industrial promotion; \n(d) rehabilitation, re -institutionalization and management of sick \nindustries; \n(e) development of women entrepreneurship. \n(4) When spending the amount of the fund in the acts under subsection \n(3), investment and expenses shall be made subject to the approved \nannual programme of the fund. \n(5) Other provisions relating to the operation and management of the fund \nshall be as prescribed. \n \n59", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "52", "title": "Provincial industrial and investment promotion fund : (1) A Province", "content": "may establish a Provincial industrial and investment promotion fund \nfor promotion and protection of industrial investment in the Province. \n  (2) The fund to be established under subsection (1) shall be \noperated and managed under the Provincial law. \n  (3) The amount of the fund under subsection (1) may be \nspent in the acts mentioned in sub-section (3) of section 51.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "53", "title": "Facilities not to be provided in duplication : (1) When providing", "content": "services, facilities or concessions to any industry under this Act or the \nprevailing law, the Government of Nepal or Provincial Government \nshall not provide any service, facility or concession in duplication. \n  (2) The Government of Nepal shall give information of the \nservices, facilities or concessions provided to any industry under this \nAct to the concerned Ministry or body of the Province in which the \nindustry is located, and the Provincia l Government shall provide \ninformation of the services, facilities or concessions provided by it to \nany industry under the Provincial law to the Department.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "54", "title": "Provisions relating to corporate social responsibility: (1) A medium or", "content": "large industry or cotta ge or small industry with annual turnover of \nmore than one hundred fifty million rupees shall set aside at least one \npercent of its annual net profits in each fiscal year for the purpose of \nperforming the corporate social responsibility. \n  (2) The amount set aside under subsection (1) shall be spent \nin such areas as prescribed, upon making annual plan s and \nprogrammes. \n \n60 \n \n  (3) An industry shall submit details on the programmes \ncompleted in each fiscal year under subsection (2) and amounts spent \nin such program mes to the concerned industry registration body \nwithin six months after the end of the fiscal year. \n  (4) The amount set aside for the corporate social \nresponsibility under subsection (1) may be deducted as expenses for \nthe purpose of income tax.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "55", "title": "Power to declare industrial village, industrial cluster, industrial zone,", "content": "special economic zone or industrial corridor : (1) The Government of \nNepal may, by publishing a noti ce in the Nepal Gazette, and upon \nsetting criteria, declare any part or place of the cou ntry with ample \npotentialities and opportunities for industrial development as an \nindustrial village, industrial cluster, industrial zone, special economic \nzone or industrial corridor. \n  (2) The services, facilities and concession s to which other \nindustries are entitled under this Act and the prevailing laws shall be \nprovided to the industrial village, industrial cluster, industrial zone, \nspecial economic zone or industrial corridor declared under subsection \n(1).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "56", "title": "Prohibition onmaking building or settlem ent: (1) No residential or", "content": "other building of any type or settlement may be made within such area \nof, and distance from, an industrial village, industrial zone and special \neconomic zone to be established after the commencement of this Act \nas specified by the Government of Nepal by publishing a notice  in the \nNepal Gazette. \n \n61 \n \n  (2)  In prevention of making a residential building or other \nbuilding or settlement in a private land of any person situated within \nthe area and distance specified under subsection (1) r esults in a loss, \ndamage, the Government of Nepal shall provide a reasonable \ncompensation to the concerned person within such time -limit and by \nfulfilling such procedures as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "57", "title": "Electronic means may be used : The industry registration body may", "content": "make necessary provisions for performing such functions relating to \nadministration of industries as prescribed  under this Act through \nelectronic means, in accordance with the prevailing law relating to \nelectronic transactions, to make such functions simple and easy.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "58", "title": "Provisions relating to automatic approval process may be made : (1)", "content": "The Government of Nepal may  execute s ervices ranging from  the \nregistration to dissolution of and matters including the type of \nindustries, nature of industries and threshold o f investments in \naccordance with this Act and other prevailing law s through the \nautomatic route to make the pro cedures relating to the administration \nof industries simple, easy and predictable. \n(2) Other provisions relating to  the procedures for automatic \napproval under subsection (1) shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "59", "title": "Power of attorney may be given : (1) An industry or person who has", "content": "ownership on the industry may give a power of attorney to another \nperson to perform any or all of the acts, actions required to be \nperformed by that person.  \n \n62 \n \n  (2) In order to perform act in accordance with a power of \nattorney given under subsection (1), such power of attorney shall be \nnotarized and provided to the industry registration body. The industry \nregistration body may, if it so considers necessary, inspect the original \nof such a power of attorney.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "60", "title": "Special provisions relating to extension of time -limit or re -", "content": "registration: (1) An industry which was registered under the prevailing \nlaw at the time of commencement of this Act and could not commence \nits operation, commercial production or transaction  because of the \nexpiration of the time -limit for the commencement of the operation, \ncommercial production or transaction of the industry or an industry \nwhich has expired the time -limit upon being unable to commence its \noperation, commercial production or transaction even within  the \npreviously extended time-limit may, for one time, make an application \nto the industry registration body for the extension of the time -limit \nwithin three months after the commencement of this Act. \n  (2) If, upon examining the application received under \nsubsection (1), the industry registration body sees a reasonable reason \nfor extending the time-limit, it may extend the time-limit by collecting \nthe following delay fee and fulfilling the procedures under this Act: \n(a) at the rate of five thousand rupees per year in the case of a micro -\nindustries; \n(b) at the rate of fifteen thousand rupees per year in the case of a \ncottageand small industry; \n \n63 \n \n(c) at the rate of fi fty thousand rupees per year in the case of a medium \nindustry; \n(d) at the rate of one hundred thousand rupees per year in the case of a \nlarge industry.  \n(3) Notice of a decision on the extension of the time -limit of any industry \nunder subsection (2) shall be given to the concerned applicant within \nseven working days after the decision.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "61", "title": "Power of Local Level to perform functions relating to administration", "content": "of industries: The Local Level may perform functions relating to the \nregistration, administration and  regulation of micro -enterprises, and \ncottage and small industries with the fixed capital not exceeding the \namount as specified in the Provincial law, as provided in the Federal \nand Provincial laws.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "62", "title": "Application may be made : If any decision or function required to be", "content": "made or performed is not made or performed within the specified \nperiod under this Act, except for matters falling under jurisdiction of \nthe Board, Province and Local Level, the aggrieved party may make \napplication to the Ministry.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "63", "title": "Delegation of powers: (1) The Board may, as required, delegate some", "content": "of the powers conferred on it under this Act or the rules framed \nhereunder to the Secretary of the Ministry, Director General of the \nDepartment or a gazette officer employee of the Government of Nepal \nor the Provincial Government or Local Level. \n \n64 \n \n  (2) The Department may, as required, delegate some of the \npowers conferred on it under this Act or the rules framed under this \nAct to any gazetted officer employee of the Government of Nepal.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "64", "title": "Power to remove difficulties: If there arises any difficulty or obstacle", "content": "in the implementation of this Act, the Government of Nepal may \nremove such a difficulty or obstacle by publishing a notice  in the \nNepal Gazette.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "65", "title": "Power to make alteration in the Schedule : The Government of Nepal", "content": "may, by a notification in the Nepal gazette, make necessary alteration, \naddition or deletion or revision in the Schedule.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "66", "title": "This Act to prevail: The matters contained herein shall be governed by", "content": "this Act and the other matters by the prevailing law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "67", "title": "Power to make rules: The Government of Nepal may frame necessary", "content": "rules for the implementation of this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "68", "title": "Power to make and enforce Directives, Procedures or Standards : (1)", "content": "The Government of Nepal may, subject to this Act and the rules \nframed hereunder, make and enforce necessary Directives, Procedures \nor Standards on the following matters, to make the functions relating \nto the administration of industries easy and simple: \n  (a) registration and regulation of industries; \n  (b) promotion of domestic products; \n(c) incentives, exemptions, facilities or concessions to be provided to \nindustries; \n(d) sick industries; \n \n65 \n \n(e) industrial zones, industrial corridors, industrial clusters and industrial \nvillages; \n(f)  operation and management of the fund; \n(g) application of electronic means to the delivery of services; \n(h) automated process for investment approval; \n(i) modus operandi of the Nepal business forum; \n(j) operation of the one stop service centre; \n(k) corporate social responsibility. \n(2) Notwithstanding anything contained in sub -section (1), the Ministry \nmay make and enforce necessary standard operating procedures on, \ninter alia, the process for electronic delivery of services.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "69", "title": "Repeal and saving : (1) The Industrial Enterprises Act, 2073(2016)is", "content": "hereby repealed. \n  (2) All acts and actions performed under the Industrial \nEnterprises Act, 2073 ( 2016…) shall be deemed to be performed \nunder this Act. \n \n66 \n \nSchedule-1 \n(Relating to Section 8) \nIndustries Requiring Permission", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "1", "title": "Industries producing arms, ammunition, gunpowder or", "content": "explosives;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Security printing, bank notes and coin industries;", "content": "3.  \n \nIndustries producing cigarette, bidi, cigar, chewing tobacco and \nother goods utilizing tobacco as the basic raw materials, and \nelectronic cigarettes;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Microbrewery, beer, alcohol, or alcoholic substances producing", "content": "industries;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Stone, ballast, sand excavation, processing industries;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Industries producing radio communication equipment;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Industries like excavation of precious minerals and petroleum", "content": "products;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Liquefied petroleum gas (L.P.G) refiling industries;", "content": "9.  \n \nAll kinds of industries producing drone products or providing \nservices through drone; \n10.  \n \nOther industries requiring permission under the prevalent laws.  \n \n67 \n \nSchedule-2 \n(Relating to clause (b) of subsection (1) of Section 17) \nCottage Industries", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "1", "title": "Handloom, pedal -loom, semi -automatic loom, wra pping, dyeing and", "content": "printing, tailoring (other than readymade  garments) and knitting with \ntraditional technology;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Hand knitted woollen and silk mats and blankets (Radi, Pakhi), carpets,", "content": "pashmina, garments, hand-made paper and goods made thereof;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "3", "title": "Goods based on traditional skill;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Traditional sculpturing;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Hand-made utensils made from metals such as copper, Pittal, Dhalout,", "content": "brass and German silver, and handicrafts;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Hand-made utensils and traditional tools of domestic use made from iron", "content": "such as knifes,Chulesi, Khukuri, sickle, Kuto, Kodalo;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Hand-made gold or silver ornaments, goods, utensils (precious, semi-", "content": "precious, and inclusive of those with ordinary stones);", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Industries cutting p recious, semi -precious and ordinary stones available", "content": "domestically cutting, rural tanning/hand-made leather goods;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Industries based on natural fibres such as zute, sabia grass, Choya, Bab iyo,", "content": "cotton thread, allo;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "Stone arts (stone carved goods);", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "11", "title": "Paubha, thanka art  and other traditional ……chitrakala;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "Masks and putali and dolls reflecting traditional culture;", "content": "68", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "Different kinds of handicraft goods reflecting traditional culture, musical", "content": "instruments and art;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "Wood, bone and horn, clay , rock, and mineral artistic goods, ceramics and", "content": "clay pots;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "16", "title": "Hand printed brick industries.", "content": "69 \n \n \nSchedule-3 \n(Relating to clause (a) of subsection (2) of Section 17) \nEnergy-Based Industries", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "1", "title": "Industries generating energy from water resources, wind, solar power, coal,", "content": "natural oil and fuel or gas, biomass or other sources, industries \nmanufacturing machines/equipment to be used for the generation of such \nenergy;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Electricity transmission lines;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "3", "title": "Electricity distribution system;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Energy based on bio-gas;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Electric energy to be produced as a co-production of the sugar industry;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Energy potentiality study.", "content": "70 \n \n \nSchedule-4 \n(Relating to clause (c) of subsection (2) of Section 17) \nIndustries Based on Agriculture and Forest Products", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "1", "title": "Fruits farming or fruits processing;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Production, processing and storage of food products;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "3", "title": "Animal husbandry, birds farming (including ostrich), animal breeding,", "content": "challa kadne business, and production and processing of meat;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Industries producing milk and processing of dairy products;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Fishery, production, processing and packaging of  fry;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Industries producing animal feed from agro -products as the primary raw", "content": "materials;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Silk farming and  processing;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Tea garden, tea processing;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Coffee farming and coffee processing;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "Herbs farming, herbs processing;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "11", "title": "Production of vegetable seeds;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "Vegetable farming, vegetable processing;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "Establishment and operation of green-houses;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "Bee keeping (bee breeding, honey production and processing;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "15", "title": "Floriculture, flower processing (making of garland, decoration, making", "content": "bouquet, including  production of seeds);", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "16", "title": "Nursery business, establishment, protection and management of botanical", "content": "gardens, inclusive of tissue culture;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "17", "title": "R ubber farming, preliminary processing and operation of rubber;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "18", "title": "Operation and management of cold stores, agriculture markets;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "19", "title": "Establishment and management of a community, leasehold, partnership,", "content": "private forest and agriculture forest, and other non-timber forest products;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "20", "title": "Commercial farming and processing of cash crops (such as sugarcane,", "content": "cotton (kapas), sanpat, sajiwan, sweet sargam, stevia…., tobacco, zute, \n \n71 \n \nalaichi, keshar, oil seed. Mashala cultivation, dalahan, etc. and pdo duction \nof their seeds);", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "21", "title": "Bet, bamboo farming, bet, bamboo and other natural fibre products;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "22", "title": "Processing of seeds;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "23", "title": "Wood industries including shaw-mills and furniture;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "24", "title": "Wood industries such as parqueting, seasoning, treatment plant, ply wood,", "content": "composite, board;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "25", "title": "Industries based on other non-timber forest products including paper  and", "content": "resin;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "26", "title": "Industries producing mushroom, tissue culture  (producing plants through", "content": "new technology), agroforest;", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "27", "title": "Cotton farming, production and processing of cotton and cotton seeds.", "content": "72 \n \nSchedule-5 \n(Relating to clause (e) of subsection 2 of Section 17) \nInfrastructure Industries", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "1", "title": "Road, bridge, tunnel;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Ropeway, railway, tram, trolley bus, monorail and sliding car;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "3", "title": "Runway/airport;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Industrial structure and infrastructure complex;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Assembly conference centre;", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Water supply and distribution;", "content": null, "children": []}, {"tier": 2, "n